{
 "command": "cat tests/fxdata.py; cat Makefile; grep -rn \"FX_FIXTURES\" . --exclude-dir=.git | head; ls -R . | grep -v pyc | head -40",
 "description": "Inspect fixture loader and config"
}

{
 "mode": "filter",
 "query": "LEDGERLINE_FX_FIXTURES fx fixtures"
}

{
 "command": "sed -n 1,25p docs/testing.md; ls tests/fixtures/fx 2>&1 | head; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30",
 "description": "Read testing docs and rerun with fixtures env"
}

{
 "command": "cat scripts/gen_fx_fixtures.py; git status --short; git check-ignore tests/fixtures/fx",
 "description": "Inspect fixture generator script"
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -30; git status --short",
 "description": "Generate FX fixtures and rerun fast tests"
}

